#![cfg(unix)]

use std::fs;
use std::process::Command;

const ALL: &str = "workspace_only = false\ninclude_deps = true\n";
const NO_DEPS: &str = "workspace_only = true\ninclude_deps = false\n";
const NO_DEPS_0_5: &str = "workspace_only = false\ninclude_deps = false\n";
const WORKSPACE_ONLY_0_5: &str = "workspace_only = true\ninclude_deps = true\n";

fn lock(tool_version: &str, scope: &str) -> String {
    format!(
        "# Auto-generated by unsafe-budget. Do not edit manually.\n\n\
         tool_version = \"{tool_version}\"\nanalyzer_id = \"rustc_unsafe_lint\"\n\n\
         [scope]\n{scope}features = []\nall_features = false\nno_default_features = false\n\
         all_targets = false\ntargets = []\n\n[totals]\nworkspace_unsafe = 2\n"
    )
}

#[test]
fn accept_unsafe_compares_the_scope_a_lock_reads_as() {
    let script = include_str!("../scripts/accept-unsafe.sh");
    let start = script.find("\nheader() {").unwrap();
    let header = &script[start..start + script[start..].find("\n}\n").unwrap() + 3];

    // committed lock's scope -> artifact lock's scope -> accepted
    let cases = [
        (ALL, ALL, true),
        (ALL, NO_DEPS, false),
        (NO_DEPS_0_5, NO_DEPS, true),
        (NO_DEPS_0_5, ALL, false),
        (WORKSPACE_ONLY_0_5, NO_DEPS, true),
        (WORKSPACE_ONLY_0_5, ALL, false),
        (NO_DEPS, NO_DEPS, true),
    ];
    let tmp = tempfile::tempdir().unwrap();
    let (old, new) = (tmp.path().join("old.lock"), tmp.path().join("new.lock"));
    for (committed, artifact, accepted) in cases {
        fs::write(&old, lock("0.5.2", committed)).unwrap();
        fs::write(&new, lock("0.6.0", artifact)).unwrap();
        let status = Command::new("bash")
            .arg("-c")
            .arg(format!("{header}\ndiff <(header \"$1\") <(header \"$2\")"))
            .args(["bash".as_ref(), old.as_os_str(), new.as_os_str()])
            .status()
            .unwrap();
        assert_eq!(status.success(), accepted, "{committed:?} -> {artifact:?}");
    }
}
